      '<g ' + SW + '><line x1="18" y1="82" x2="70" y2="82"/><circle cx="12" cy="78" r="8" fill="' + V + '" stroke="none"/></g>' +
      '<g>' + rot("0 70 82;-72 70 82;0 70 82", 0, 0, "4s") +
