    if(voice)u.voice=voice;
    try{u.rate=parseFloat(rateSel.value)||1;}catch(e){u.rate=1;}
    u.onend=function(){
      if(g!==gen||state!=='playing')return;
      progress(i);
      savePlace(i+1);
      speak(i+1,g);
    };
    u.onerror=function(){
      if(g!==gen||state!=='playing')return;
      /* Phone app-switch (v1.0.6): the OS kills the utterance mid-chunk.
         Advancing on error cascades chunk-to-chunk until speak() runs past
         the end and finish() CLEARS the saved place — the reader then
         restarted from the top. On a hidden page an error means suspended,
         not failed: keep the place at the current chunk and stop here. */
      if(document.hidden){savePlace(idx);gen++;disarm();state='idle';setPlay();return;}
      speak(i+1,g);
    };
    try{synth.speak(u);}catch(e){if(g===gen&&state==='playing')speak(i+1,g);}
  }
  function doPlay(){
    if(state==='playing'){
      try{synth.pause();}catch(e){}
      state='paused';savePlace(idx);setPlay();disarm();unlock();return;
    }
    if(state==='paused'){
      try{synth.resume();}catch(e){}
      state='playing';setPlay();arm();lock();return;
    }
    gen++;
    try{synth.cancel();}catch(e){}
    var p=loadPlace();
    state='playing';setPlay();arm();lock();
    speak(p?p.i:0,gen);
  }
  function finish(){
    gen++;disarm();unlock();
    try{synth.cancel();}catch(e){}
    clearPlace();
    state='idle';idx=0;clearHi();progress(-1);setPlay();
  }
  function stopAll(){
    gen++;disarm();unlock();
    try{synth.cancel();}catch(e){}
    savePlace(idx);
    state='idle';idx=0;clearHi();progress(-1);setPlay();
  }
  play.addEventListener('click',doPlay);
  stopBtn.addEventListener('click',stopAll);
  rateSel.addEventListener('change',function(){
    if(state!=='playing')return;
    gen++;
    try{synth.cancel();}catch(e){}
    speak(idx,gen);
  });
