/* ---- reader chrome ---- */
var ROW=
'<div class="dg-row">'
+'<button type="button" class="dg-play" aria-pressed="false">\u25B6 dogear</button>'
+'<button type="button" class="dg-stop" disabled aria-label="Stop reading">\u23F9</button>'
+'<label class="dg-rate">Speed <select class="dg-speed" aria-label="Reading speed">'
+'<option value="0.8">0.8\u00D7</option><option value="1" selected>1\u00D7</option>'
+'<option value="1.25">1.25\u00D7</option><option value="1.5">1.5\u00D7</option>'
+'</select></label>'
+'<div class="dg-progress" aria-hidden="true"><span class="dg-fill"></span></div>'
+'</div>'
+'<div class="dg-sub"><span>document in, place kept, resume anywhere</span>'
+'<a href="'+HOME+'" target="_blank" rel="noopener">getdogear.app</a></div>';

function boot(){
  if(!document.querySelector('[data-dogear]'))return;
  if(!document.querySelector('style[data-dogear-css]')){
    var st=document.createElement('style');
    st.setAttribute('data-dogear-css','1');
    st.textContent=CSS;
    document.head.appendChild(st);
  }
  var mounts=document.querySelectorAll('[data-dogear]');
  Array.prototype.forEach.call(mounts,function(m){init(m);});
}
/* Boot contract (v1.0.5): NEVER initialize while the document is still parsing.
   An inline script tag executes synchronously, so readable content placed after
   the embed in the HTML would otherwise be invisible to the reader — this is
   the same family as the onsmartgrid script-close incident, the getdogear
   below-mount truncation, and the worker article pages that only ever wrapped
   the headline. Deferring to DOMContentLoaded makes the reader independent of
   embed placement: no per-site script moves, one invariant for every site. */
if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded',boot);
}else{
  boot();
}

function init(mount){
  var scopeEl=mount.getAttribute('data-dogear-scope');
  var scope=scopeEl?document.querySelector(scopeEl):document.querySelector('article');
  if(!scope||!('speechSynthesis' in window)){mount.style.display='none';return;}
  mount.classList.add('dg');
  mount.innerHTML=ROW;
  var play=mount.querySelector('.dg-play'),
      stopBtn=mount.querySelector('.dg-stop'),
      rateSel=mount.querySelector('.dg-speed'),
      fill=mount.querySelector('.dg-fill');
  var synth=window.speechSynthesis;

  var select=mount.getAttribute('data-dogear-select')||'h1,h2,p,li';
  var excl=mount.getAttribute('data-dogear-exclude')||'.dg,.share-row,.news-box,.crumbs,aside,.disclaimer,.meta,.refs,.related';
  var blocks=[];
  Array.prototype.forEach.call(scope.querySelectorAll(select),function(el){
    if(el.closest(excl))return;
    if(el.textContent.replace(/\s+/g,''))blocks.push(el);
  });
  /* Orphan-text fallback (v1.0.7): some article bodies are stored as bare
     text inside a container — no <p>/<h2>/<li> markup at all. The block
     selector then matches only the headline and dek, and everything below
     the player is silently skipped (TWF "Navigating the Gig Economy and
     Taxes", found 2026-10-13: 3 spans total, body invisible to the reader).
     A container holding real direct text and NO selected block inside it
     is itself a block; only the outermost such container is taken, so its
     text is walked once, in order. Markup-rich pages are unaffected: their
     containers hold selected blocks and are never re-read. */
  var orphans=[];
  Array.prototype.forEach.call(scope.querySelectorAll('div,section,blockquote,td,dd,dt,figcaption'),function(el){
    if(el.closest(excl))return;
    if(el.querySelector(select))return;
    var direct=false;
    Array.prototype.forEach.call(el.childNodes,function(n){
      if(n.nodeType===3&&n.nodeValue.replace(/\s+/g,''))direct=true;
    });
    if(direct)orphans.push(el);
  });
  orphans=orphans.filter(function(el){
    return !orphans.some(function(o){return o!==el&&o.contains(el);});
  });
  blocks=blocks.concat(orphans);
  blocks.sort(function(a,b){
    var r=a.compareDocumentPosition(b);
    return (r&2)?1:((r&4)?-1:0);
  });

  /* split into sentences, wrap for highlight */
  var sents=[];
  blocks.forEach(function(el){
    var walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT,null,false);
    var nodes=[],n;
    while((n=walker.nextNode())){
      if(n.parentElement&&n.parentElement.closest(excl))continue; /* skip text inside excluded descendants */
      if(n.nodeValue.replace(/\s+/g,''))nodes.push(n);
    }
    nodes.forEach(function(tn){
      var parts=tn.nodeValue.split(/(?<=[.!?])\s+/);
      var frag=document.createDocumentFragment();
      parts.forEach(function(p){
        if(!p.replace(/\s+/g,''))return;
        var sp=document.createElement('span');
        sp.className='dg-sent';
        sp.textContent=p;
        frag.appendChild(sp);
        frag.appendChild(document.createTextNode(' '));
        sents.push({el:sp,text:p.replace(/\s+/g,' ').trim()});
      });
      tn.parentNode.replaceChild(frag,tn);
    });
  });
  if(!sents.length){mount.style.display='none';return;}

  /* group sentences into ~240-char spoken chunks */
  var chunks=[];
  sents.forEach(function(s){
    var t=s.text;
    while(t.length>240){
      var c=t.lastIndexOf(',',240);
      if(c<80)c=t.lastIndexOf(' ',240);
      if(c<80)c=240;
      chunks.push({el:s.el,text:t.slice(0,c+1)});
      t=t.slice(c+1).replace(/^\s+/,'');
    }
    if(t)chunks.push({el:s.el,text:t});
  });

  /* voice: prefer an English voice, Google US English first */
  var voice=null;
  function pickVoice(){
    var vs=synth.getVoices();
    if(!vs||!vs.length)return;
    var en=vs.filter(function(v){return/^en/i.test(v.lang||'');});
    en.sort(function(a,b){
      var ga=/google/i.test(a.name||'')?0:1,gb=/google/i.test(b.name||'')?0:1;
      if(ga!==gb)return ga-gb;
      var ua=/en[-_]us/i.test(a.lang||'')?0:1,ub=/en[-_]us/i.test(b.lang||'')?0:1;
      return ua-ub;
    });
    voice=(en[0]||vs[0])||null;
  }
  try{if('onvoiceschanged' in synth)synth.onvoiceschanged=pickVoice;}catch(e){}
  pickVoice();

  /* place kept: per-article chunk index in localStorage */
  function pkey(){return 'dogear:place:'+location.pathname;}
  function loadPlace(){
    try{
      var p=JSON.parse(localStorage.getItem(pkey()));
      if(p&&typeof p.i==='number'&&p.i>0&&p.i<chunks.length&&p.n===chunks.length)return p;
    }catch(e){}
    return null;
  }
  function savePlace(i){
    try{localStorage.setItem(pkey(),JSON.stringify({i:i,n:chunks.length,t:Date.now()}));}catch(e){}
  }
  function clearPlace(){try{localStorage.removeItem(pkey());}catch(e){}}

  /* screen wake lock: the display must not time out mid-article */
  var wakeLock=null;
  function lock(){
    if(!('wakeLock' in navigator))return;
    try{navigator.wakeLock.request('screen').then(function(s){wakeLock=s;},function(){});}catch(e){}
  }
  function unlock(){
    if(wakeLock){try{wakeLock.release();}catch(e){}wakeLock=null;}
  }

  var state='idle',idx=0,gen=0,keepAlive=null;
  function clearHi(){
    var h=scope.querySelector('.dg-sent.dg-on');
    if(h)h.classList.remove('dg-on');
  }
  function progress(i){
    if(fill)fill.style.width=(i<0?0:Math.round(((i+1)/chunks.length)*100))+'%';
  }
  function setPlay(){
    if(state==='playing'){play.textContent='\u23F8 Pause';}
    else if(state==='paused'){play.textContent='\u25B6 Resume';}
    else{
      var p=loadPlace();
      play.textContent=p?('\u25B6 Resume \u00B7 '+Math.round((p.i/chunks.length)*100)+'%'):'\u25B6 dogear';
    }
    play.setAttribute('aria-pressed',state==='playing'?'true':'false');
    stopBtn.disabled=(state==='idle');
  }
  /* Android Chrome suspends long utterances: nudge it awake */
  function disarm(){if(keepAlive){clearInterval(keepAlive);keepAlive=null;}}
  function arm(){
    disarm();
    keepAlive=setInterval(function(){
      try{if(state==='playing')synth.resume();}catch(e){}
    },8000);
  }
  function speak(i,g){
    if(g!==gen||state!=='playing')return;
    if(i>=chunks.length){finish();return;}
    idx=i;
    var ch=chunks[i];
    clearHi();
    ch.el.classList.add('dg-on');
    var u=new SpeechSynthesisUtterance(ch.text);
    if(voice)u.voice=voice;
    try{u.rate=parseFloat(rateSel.value)||1;}catch(e){u.rate=1;}
    u.onend=function(){
      if(g!==gen||state!=='playing')return;
      progress(i);
      savePlace(i+1);
      speak(i+1,g);
    };
    u.onerror=function(){
      if(g!==gen||state!=='playing')return;
      /* Phone app-switch (v1.0.6): the OS kills the utterance mid-chunk.
         Advancing on error cascades chunk-to-chunk until speak() runs past
         the end and finish() CLEARS the saved place — the reader then
         restarted from the top. On a hidden page an error means suspended,
         not failed: keep the place at the current chunk and stop here. */
      if(document.hidden){savePlace(idx);gen++;disarm();state='idle';setPlay();return;}
      speak(i+1,g);
    };
    try{synth.speak(u);}catch(e){if(g===gen&&state==='playing')speak(i+1,g);}
  }
  function doPlay(){
    if(state==='playing'){
      try{synth.pause();}catch(e){}
      state='paused';savePlace(idx);setPlay();disarm();unlock();return;
    }
    if(state==='paused'){
      try{synth.resume();}catch(e){}
      state='playing';setPlay();arm();lock();return;
    }
    gen++;
    try{synth.cancel();}catch(e){}
    var p=loadPlace();
    state='playing';setPlay();arm();lock();
    speak(p?p.i:0,gen);
  }
  function finish(){
    gen++;disarm();unlock();
    try{synth.cancel();}catch(e){}
    clearPlace();
    state='idle';idx=0;clearHi();progress(-1);setPlay();
  }
  function stopAll(){
    gen++;disarm();unlock();
    try{synth.cancel();}catch(e){}
    savePlace(idx);
    state='idle';idx=0;clearHi();progress(-1);setPlay();
  }
  play.addEventListener('click',doPlay);
  stopBtn.addEventListener('click',stopAll);
  rateSel.addEventListener('change',function(){
    if(state!=='playing')return;
    gen++;
    try{synth.cancel();}catch(e){}
    speak(idx,gen);
  });
  /* leaving Chrome must not kill speech; the wake lock covers screen-off,
     and on return we re-lock and reconcile if the OS stopped the audio */
  document.addEventListener('visibilitychange',function(){
    if(document.hidden){
      unlock();disarm();
      if(state==='playing')savePlace(idx);
    }else if(state==='playing'){
      lock();arm();
      try{if(!synth.speaking&&!synth.paused){state='idle';setPlay();}}catch(e){}
    }
  });
  document.addEventListener('pagehide',function(){
    savePlace(idx);unlock();disarm();
    try{synth.cancel();}catch(e){}
  });
  setPlay();
}
})

(function () {
  var CLIP_BASE = "/selfcare/shared/clips/";
  var STILL_BASE = "/selfcare/shared/clips/stills/";
  var LS_CHAR = "scd-char"; /* "her" (default) | "him" — global across pages */

  /* ---------- character ---------- */
  function getChar() {
    try {
      var c = localStorage.getItem(LS_CHAR);
      return c === "him" ? "him" : "her";
    } catch (e) { return "her"; }
  }
  /* Returns true when the character actually changed. */
  function setChar(c) {
    c = (c === "him") ? "him" : "her";
    if (c === getChar()) return false;
    try { localStorage.setItem(LS_CHAR, c); } catch (e) {}
    return true;
  }

  /* ---------- movement table ----------
     profile: clip framing used to place overlay markers (stand | crop |
              sit | lie | lieR). nodes: lymphatic node/vessel groups shown.
     pose: still used for reduced-motion and clip placeholders. */
  var MOVES = {
    "neck-roll":    { profile: "crop",  nodes: ["cervical", "supraclavicular"], pose: "stand" },
    "shoulder-roll":{ profile: "stand", nodes: ["cervical", "supraclavicular", "axillary"], pose: "stand" },
    "chest-open":   { profile: "stand", nodes: ["axillary", "thoracic"], pose: "stand" },
    "side-stretch": { profile: "stand", nodes: ["axillary", "thoracic"], pose: "stand" },
    "forward-roll": { profile: "stand", nodes: ["thoracic", "abdominal"], pose: "stand" },
    "trunk-twist":  { profile: "lie",   nodes: ["thoracic", "abdominal", "inguinal"], pose: "lie" },
    "bridge":       { profile: "lieR",  nodes: ["abdominal", "inguinal"], pose: "lie" },
    "knee-chest":   { profile: "lie",   nodes: ["abdominal", "inguinal", "popliteal"], pose: "lie" },
    "leg-floss":    { profile: "lie",   nodes: ["inguinal", "popliteal"], pose: "lie" },
    "belly-breathe":{ profile: "sit",   nodes: ["thoracic", "abdominal"], pose: "sit" },
    "collarbone":   { profile: "crop",  nodes: ["supraclavicular", "cervical"], pose: "stand" },
    "cactus":       { profile: "stand", nodes: ["axillary", "thoracic"], pose: "stand" },
    "cat-cow":      { profile: "sit",   nodes: ["thoracic", "abdominal"], pose: "sit" },
    "neck-tilt":    { profile: "stand", nodes: ["cervical", "supraclavicular"], pose: "stand" },
    "arm-sweep":    { profile: "stand", nodes: ["cervical", "axillary", "thoracic"], pose: "stand" },
    "calf-raise":   { profile: "stand", nodes: ["popliteal", "inguinal"], pose: "stand" },
    "good-morning": { profile: "stand", nodes: ["abdominal", "inguinal"], pose: "stand" },
    "knee-arm":     { profile: "stand", nodes: ["inguinal", "axillary", "popliteal"], pose: "stand" },
    "bounce":       { profile: "stand", nodes: ["cervical", "axillary", "inguinal", "popliteal"], pose: "stand" }
  };

  /* Approximate node zones in overlay units (viewBox 0 0 50 100 matches the
     1:2 portrait clips, so markers scale uniformly with the figure). */
  var PROFILES = {
    stand: {
      cervical: [[21.5, 14], [28.5, 14]],
      supraclavicular: [[20, 24], [30, 24]],
      axillary: [[14, 29], [36, 29]],
      thoracic: "M25,28 C25,36 25,42 25,48",
      abdominal: [[25, 50]],
      inguinal: [[20.5, 56], [29.5, 56]],
      popliteal: [[22, 71], [28, 71]]
    },
    crop: {
      cervical: [[22, 15], [28, 15]],
      supraclavicular: [[20.5, 27], [29.5, 27]],
      axillary: [[14.5, 32], [35.5, 32]],
      thoracic: "M25,30 C25,38 25,44 25,52",
      abdominal: [[25, 55]]
    },
    sit: {
      cervical: [[22, 13], [28, 13]],
      supraclavicular: [[20.5, 24], [29.5, 24]],
      axillary: [[14.5, 29], [35.5, 29]],
      thoracic: "M25,28 C25,34 25,40 25,46",
      abdominal: [[25, 47]],
      inguinal: [[21, 54], [29, 54]]
    },
    lie: {
      cervical: [[8, 58]],
      supraclavicular: [[12, 60]],
      axillary: [[17, 62]],
      thoracic: "M12,60 C20,61 26,61 32,61",
      abdominal: [[24, 60]],
      inguinal: [[29, 58]],
      popliteal: [[36, 50]]
    },
    lieR: {
      cervical: [[42, 58]],
      supraclavicular: [[38, 60]],
      axillary: [[33, 62]],
      thoracic: "M38,60 C30,61 24,61 18,61",
      abdominal: [[26, 60]],
      inguinal: [[21, 58]],
      popliteal: [[14, 50]]
    }
  };

  /* Clips still being generated — render a matching character still instead.
     TODO(clip-retry): replace each entry with its generated mp4 and delete
     the placeholder branch in resolve(); see clips/MAPPING.md. */
  var MISSING = {
    "belly-breathe:her": "her-seated",
    "bridge:her": "her-lying",
    "neck-tilt:him": "him-neutral",
    "calf-raise:him": "him-neutral",
    "leg-floss:him": "him-lying"
  };

  var POSE_STILL = { stand: "neutral", sit: "seated", lie: "lying" };

  function prefersReduced() {
    try {
      return window.matchMedia &&
        window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    } catch (e) { return false; }
  }

  /* Resolve a movement to playable media for the current character.
     {kind:"video",src} | {kind:"still",src,placeholder} */
  function resolve(move) {
    var char = getChar(), key = move + ":" + char;
    if (MISSING[key]) {
      return { kind: "still", src: STILL_BASE + MISSING[key] + ".webp", placeholder: true };
    }
    if (prefersReduced()) {
      var cfg = MOVES[move] || { pose: "stand" };
      return { kind: "still", src: STILL_BASE + char + "-" + (POSE_STILL[cfg.pose] || "neutral") + ".webp", placeholder: false };
    }
    return { kind: "video", src: CLIP_BASE + move + "-" + char + ".mp4", placeholder: false };
  }

  /* ---------- overlay layer system ----------
     Each layer: { id, label, render(move) -> svg inner markup }.
     Future anatomy layers (muscles, skeleton, nervous system) register here
     with the same shape — the player and figure code stay untouched. */
  var LAYERS = {
    lymphatic: {
      id: "lymphatic",
      label: "Lymphatic",
      render: function (move) {
        var cfg = MOVES[move];
        if (!cfg) return "";
        var prof = PROFILES[cfg.profile];
        if (!prof) return "";
        var s = "";
        cfg.nodes.forEach(function (n, ni) {
          if (n === "thoracic") {
            s += '<path class="vessel" d="' + prof.thoracic + '"/>';
            return;
          }
          var pts = prof[n];
          if (!pts) return;
          pts.forEach(function (pt, pi) {
            s += '<circle class="node pulse" style="animation-delay:' +
              (((ni + pi) * 0.45) % 2).toFixed(2) +
              's" cx="' + pt[0] + '" cy="' + pt[1] + '" r="1.5"/>';
          });
        });
        return s;
      }
    }
    /* muscles:  { id:"muscles",  label:"Muscles",  render: function(move){...} },
       skeleton: { id:"skeleton", label:"Skeleton", render: function(move){...} },
       nerves:   { id:"nerves",   label:"Nervous system", render: function(move){...} } */
  };
  var ACTIVE_LAYERS = ["lymphatic"];

  function renderOverlay(move) {
    var out = "";
    ACTIVE_LAYERS.forEach(function (id) {
      var L = LAYERS[id];
      if (L && typeof L.render === "function") {
        out += '<g class="lyr-' + L.id + '">' + L.render(move) + "</g>";
      }
    });
    return out;
  }

  /* ---------- shared styles (injected once) ---------- */
  var stylesDone = false;
  function ensureStyles() {
    if (stylesDone) return;
    stylesDone = true;
    var css =
      ".scdemo{position:relative;max-width:280px;margin:0 auto;border-radius:16px;overflow:hidden;background:#0b1020;border:1px solid #26314d}" +
      ".scdemo-stage{position:relative}" +
      ".scdemo video,.scdemo img{display:block;width:100%;aspect-ratio:1/2;object-fit:cover;background:#0b1020}" +
      ".scdemo-overlay{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}" +
      ".scdemo .node{fill:#7ef9d2;stroke:#0b1020;stroke-width:.25;opacity:.8}" +
      ".scdemo .vessel{stroke:#7ef9d2;stroke-width:.8;fill:none;opacity:.45;stroke-linecap:round}" +
      ".scdemo .pulse{transform-box:fill-box;transform-origin:center;animation:scd-pulse 2.6s ease-in-out infinite}" +
      "@keyframes scd-pulse{0%,100%{opacity:.45}50%{opacity:.95}}" +
      "@media (prefers-reduced-motion:reduce){.scdemo .pulse{animation:none;opacity:.8}}" +
      ".scdemo-badge{position:absolute;top:8px;left:8px;right:8px;text-align:center;font-size:11px;line-height:1.4;padding:4px 8px;border-radius:999px;background:rgba(11,16,32,.8);color:#cfe3ff;border:1px solid #33415f}" +
      ".scdemo-ctl{position:absolute;right:8px;bottom:8px;width:36px;height:36px;border-radius:50%;border:1px solid #33415f;background:rgba(11,16,32,.82);color:#e8f0ff;font-size:14px;line-height:1;cursor:pointer;display:flex;align-items:center;justify-content:center;padding:0}" +
      ".scdemo-ctl:hover{background:rgba(38,50,88,.92)}" +
      ".scdemo-ctl:focus-visible{outline:2px solid #7ef9d2;outline-offset:2px}" +
      ".scdemo-cap{margin:0;padding:7px 10px;font-size:11px;line-height:1.45;color:#9fb2d8;background:rgba(11,16,32,.94);text-align:center}" +
      ".char-toggle{display:inline-flex;gap:6px;padding:3px;border:1px solid #26314d;border-radius:999px;background:#0f1526}" +
      ".char-toggle button{border:0;border-radius:999px;padding:7px 18px;font-size:13px;background:transparent;color:#9fb2d8;cursor:pointer}" +
      ".char-toggle button[aria-pressed=\"true\"]{background:#2b3c5e;color:#fff}";
    var st = document.createElement("style");
    st.setAttribute("data-scdemos", "1");
    st.textContent = css;
    document.head.appendChild(st);
  }

  function esc(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;")
      .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }

  /* Render the full demonstrator figure (media + overlay + caption) into el. */
  function renderFigure(el, move) {
    if (!el) return;
    ensureStyles();
    var res = resolve(move);
    var mediaHtml;
    if (res.kind === "video") {
      mediaHtml = '<video src="' + esc(res.src) +
